generated_pydough:
# Find the names of students who did NOT take any courses from the 'Biology' department.
# We filter the 'students' collection. For each student, we check their 'take' (courses taken).
# We use HASNOT to ensure that none of their taken courses are from the 'Biology' department.
students_no_biology_courses = students.WHERE(
    HASNOT(take.WHERE(
        course.dept_name == 'Biology'
    )) == 1
).CALCULATE(
    student_name=name
)

most_common_characteristic = product_characteristic.CALCULATE(
    char_name=characteristic.characteristic_name
).PARTITION(
    name="char_groups",
    by=(char_name)
).CALCULATE(
    characteristic_name=char_name,
    occurrence_count=COUNT(product_characteristic)
).TOP_K(1, by=occurrence_count.DESC()).CALCULATE(
    name=characteristic_name
)
